      console.log(`    acct=${p.account?.number ?? acctById[p.account?.id]}, gross=${p.amountGross}, vatType=${p.vatType?.id}`);
    }
  }

  if (createdIds.length < 2) { console.log("Could not create both vouchers"); return; }

